"""
HOURGLASS v0.1.0 - build hook.  Writes hourglass_pkg.vhd next to this file (pure python, system python3).
Heirloom from the video clips; still WIN_20230618_20_23_10 t0.5 (clip frame 9 at 0.528 s).

The patch, as fitted (.heirloom_work/rb_hourglass/notes.md), in virtual 1080-line coordinates:
  W(y)  = S(y) + A(y) sin(theta),  theta = theta0 + y / lambda       (the scrolling vertical wave)
  S(y)  = 107 + kW P(|u|),  P = 366.7|u| + 80.9 u^2 - 144.9 |u|^3,  u = (y - 530) / 540   (the hourglass)
  A(y)  = (219 + 44 (1 - |u|)) gA                                     (wave amplitude, gA = P12)
  key   : |X| < W (+ camera);  halo outside: e = |X| - W,  G = 15 + 185 (1 - e/L)^1.6, R = 0.87 G
  inside: R = T1r[E, pg],  G = T1g[E, pg] + T2g[D9, pg] - 80,  B = T2b[D9, pg]
          E = W + 0.2 X (16-px bins from -160),  D9 = W - 0.9 |X| (16-px bins from -256),
          pg = |y - 520| / 35 (16 pages); indices 2x2-dithered.
  T1 / T2 are binned means over the 317 frames of the clip (G backfitted additively), R histogram-matched.

ROMs written:
  C_HG_T1   1024 x 16  (E bin * 16 + page): R1 & (G1 + 32)
  C_HG_T2   1024 x 16  (D9 bin * 16 + page): (G2 + 48) & B2
  C_HG_SP   512 x 16   0..255: quarter sine round(32767 sin(pi/2 (i + 0.5)/256)) ;  256..511: P(i/256) in 1/8 px
  C_HG_GLOW 512 x 8    185 (1 - i/256)^1.6 for i < 256, 0 above
  C_HG_EXP2 256 x 16   round(32768 * 2^(i/256))
"""
import math
import os

HERE = os.path.dirname(os.path.abspath(__file__))

T1_HEX = ""
T2_HEX = ""


def words(h):
    return [int(h[i:i + 4], 16) for i in range(0, len(h), 4)]


def tables():
    t1 = words(T1_HEX)
    t2 = words(T2_HEX)
    sp = [int(round(32767 * math.sin(math.pi / 2 * (i + 0.5) / 256))) for i in range(256)]
    for i in range(256):
        a = i / 256.0
        sp.append(int(round(8 * (366.7 * a + 80.9 * a * a - 144.9 * a ** 3))))
    glow = [int(round(185 * (1 - i / 256.0) ** 1.6)) if i < 256 else 0 for i in range(512)]
    exp2 = [min(65535, int(round(32768 * 2 ** (i / 256.0)))) for i in range(256)]
    return t1, t2, sp, glow, exp2


def rom(lines, name, typ, n, width, vals, hexw):
    lines.append("    type %s is array (0 to %d) of std_logic_vector(%d downto 0);" % (typ, n - 1, width - 1))
    lines.append("    constant %s : %s := (" % (name, typ))
    for i in range(0, n, 8):
        row = ", ".join('x"%0*x"' % (hexw, vals[j]) for j in range(i, i + 8))
        lines.append("        " + row + ("," if i + 8 < n else ""))
    lines.append("    );")


def main():
    t1, t2, sp, glow, exp2 = tables()
    L = ["-- Generated by hourglass.py: do not edit.  Colour tables, quarter sine + hourglass profile, glow, exp2.",
         "library ieee;", "use ieee.std_logic_1164.all;", "use ieee.numeric_std.all;", "",
         "package hourglass_pkg is"]
    rom(L, "C_HG_T1", "t_hg_t1", 1024, 16, t1, 4)
    rom(L, "C_HG_T2", "t_hg_t2", 1024, 16, t2, 4)
    rom(L, "C_HG_SP", "t_hg_sp", 512, 16, sp, 4)
    rom(L, "C_HG_GLOW", "t_hg_glow", 512, 8, glow, 2)
    rom(L, "C_HG_EXP2", "t_hg_exp2", 256, 16, exp2, 4)
    L.append("end package hourglass_pkg;")
    with open(os.path.join(HERE, "hourglass_pkg.vhd"), "w") as f:
        f.write("\n".join(L) + "\n")
    print("hourglass_pkg.vhd written (T1/T2 1024 x 16, SP 512 x 16, glow 512 x 8, exp2 256 x 16)")


if __name__ == "__main__":
    main()
